import re

def differentiate(polynomial: str, x: int) -> int:
    terms = polynomial.replace(' ', '').split('+')

    total = 0

    for term in terms:
        if not term:
            continue

        if 'x' not in term:
            continue

        if '^' in term:
            coeff_part, power_part = term.split('^')
            power = int(power_part)
        else:
            power = 1
            coeff_part = term.replace('x', '')

        if coeff_part == '' or coeff_part == '+':
            coeff = 1
        elif coeff_part == '-':
            coeff = -1
        else:
            coeff = int(coeff_part)

        if power == 0:
            continue

        new_coeff = coeff * power
        new_power = power - 1

        if new_power == 0:
            total += new_coeff
        else:
            total += new_coeff * (x ** new_power)

    return total
